#!/usr/bin/env python3\nfrom __future__ import annotations\nimport csv, json, os, re, subprocess\nfrom collections import defaultdict\nfrom pathlib import Path\nROOT = Path(__file__).resolve().parents[2]\nCONTROL = Path(os.environ.get("JASS_CONTROL_REPO_DIR", "/srv/jass/control"))\nART = Path(os.environ["JASS_ARTEFACT_DIR"])\nSCHEMA = "jass.r2_retention_audit.v1"\nTERMINAL = "R2_RETENTION_AUDIT_COMPLETE_V1"\nJOB_RE = re.compile(r"\\b(?:cpx62|ccx33|home)-[A-Za-z0-9._-]+\\b")\n\ndef collect_refs(root: Path) -> set[str]:\n    out = set()\n    if not root.exists(): return out\n    for p in root.rglob("*"):\n        if not p.is_file() or p.is_symlink(): continue\n        try:\n            if p.stat().st_size > 4 * 1024 * 1024: continue\n            text = p.read_text(encoding="utf-8", errors="ignore")\n        except OSError:\n            continue\n        out.update(JOB_RE.findall(text))\n    return out\n\ndef main() -> int:\n    ART.mkdir(parents=True, exist_ok=True)\n    rclone = os.environ.get("RCLONE_BIN", "rclone")\n    proc = subprocess.run([rclone, "lsf", "r2:jass-data", "--recursive", "--files-only", "--format", "sp", "--separator", ";"], check=True, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=1800)\n    by_job = defaultdict(lambda: {"bytes": 0, "objects": 0})\n    by_top = defaultdict(lambda: {"bytes": 0, "objects": 0})\n    for line in proc.stdout.splitlines():\n        if not line.strip(): continue\n        size_s, path = line.split(";", 1)\n        size = int(size_s)\n        top = path.split("/", 1)[0]\n        by_top[top]["bytes"] += size; by_top[top]["objects"] += 1\n        if path.startswith("runs/"):\n            parts = path.split("/")\n            if len(parts) >= 3:\n                job = parts[1]\n                by_job[job]["bytes"] += size; by_job[job]["objects"] += 1\n    refs = collect_refs(ROOT) | collect_refs(CONTROL)\n    decisions = []\n    keep_bytes = delete_bytes = 0\n    for job, stat in sorted(by_job.items(), key=lambda kv: kv[1]["bytes"], reverse=True):\n        keep = job in refs\n        decisions.append({"job_id": job, "decision": "KEEP" if keep else "DELETE_CANDIDATE", "reason": "referenced_by_current_repo_or_control" if keep else "unreferenced_run_candidate", "bytes": stat["bytes"], "objects": stat["objects"]})\n        if keep: keep_bytes += stat["bytes"]\n        else: delete_bytes += stat["bytes"]\n    with (ART / "r2-job-retention.csv").open("x", newline="", encoding="utf-8") as f:\n        w = csv.DictWriter(f, fieldnames=["job_id","decision","reason","bytes","objects"])\n        w.writeheader(); w.writerows(decisions)\n    summary = {"schema": SCHEMA, "state": "completed", "terminal": TERMINAL, "read_only": True, "bucket": "jass-data", "total_bytes": sum(x["bytes"] for x in by_top.values()), "total_objects": sum(x["objects"] for x in by_top.values()), "top_level": dict(sorted(by_top.items())), "run_jobs": len(by_job), "referenced_jobs": sum(d["decision"] == "KEEP" for d in decisions), "delete_candidate_jobs": sum(d["decision"] == "DELETE_CANDIDATE" for d in decisions), "referenced_run_bytes": keep_bytes, "delete_candidate_run_bytes": delete_bytes, "policy": {"non_runs": "KEEP_BY_DEFAULT", "runs_referenced_by_current_jass_or_control": "KEEP", "unreferenced_runs": "DELETE_CANDIDATE_ONLY_NO_DELETION"}}\n    payload = json.dumps(summary, indent=2, sort_keys=True) + "\\n"\n    (ART / "r2-retention-summary.json").write_text(payload)\n    (ART / "scientific-summary.json").write_text(payload)\n    (ART / "RESULTS.md").write_text("# R2 retention audit\\n\\n" + payload)\n    return 0\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n